import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"5. 经济系统","description":"","frontmatter":{},"headers":[],"relativePath":"economy.md","filePath":"economy.md"}'),r={name:"economy.md"};function c(n,t,l,i,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_5-经济系统" tabindex="-1">5. 经济系统 <a class="header-anchor" href="#_5-经济系统" aria-label="Permalink to &quot;5. 经济系统&quot;">​</a></h1><h2 id="_5-1-货币就是钻石" tabindex="-1">5.1 货币就是钻石 <a class="header-anchor" href="#_5-1-货币就是钻石" aria-label="Permalink to &quot;5.1 货币就是钻石&quot;">​</a></h2><p>服务器使用 <strong>钻石</strong> 作为唯一货币，通过 XConomy 记账。</p><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>新玩家初始余额</td><td><strong>8 钻石</strong></td></tr><tr><td>转账税</td><td>0</td></tr><tr><td>银行兑换比例</td><td><strong>1 钻石 = 1 余额</strong>，双向 1:1</td></tr><tr><td>余额显示</td><td><code>/balance</code> 显示“多少钻石”</td></tr><tr><td>排行榜</td><td><code>/baltop</code></td></tr></tbody></table><blockquote><p>余额是“记账数字”，不是背包里的钻石。<code>/balance</code> 有 8，不代表背包有 8 颗钻石；需要用 <code>/bank takeout</code> 取出来。</p></blockquote><h2 id="_5-2-银行-pepperdiamond" tabindex="-1">5.2 银行（PepperDiamond） <a class="header-anchor" href="#_5-2-银行-pepperdiamond" aria-label="Permalink to &quot;5.2 银行（PepperDiamond）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/bank</code></td><td>打开银行界面</td></tr><tr><td><code>/bank add &lt;数量&gt;</code></td><td>把背包里的钻石存入余额；别名 <code>/bank save</code></td></tr><tr><td><code>/bank takeout &lt;数量&gt;</code></td><td>从余额取出钻石到背包；别名 <code>/bank get</code>、<code>/bank take</code></td></tr></tbody></table><p>银行只处理钻石，其他物品不能存入。存取是 1:1，没有手续费。</p><h2 id="_5-3-玩家转账" tabindex="-1">5.3 玩家转账 <a class="header-anchor" href="#_5-3-玩家转账" aria-label="Permalink to &quot;5.3 玩家转账&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/pay &lt;玩家&gt; &lt;金额&gt;</code></td><td>转账给对方</td></tr><tr><td><code>/paytoggle</code></td><td>开启/关闭接收转账</td></tr><tr><td><code>/balance</code></td><td>查看余额</td></tr><tr><td><code>/baltop</code></td><td>查看余额排行榜</td></tr></tbody></table><p>转账不收税。交易前确认对方身份，服务器不会自动撤回玩家之间的自愿转账。</p><h2 id="_5-4-赚钱与花钱" tabindex="-1">5.4 赚钱与花钱 <a class="header-anchor" href="#_5-4-赚钱与花钱" aria-label="Permalink to &quot;5.4 赚钱与花钱&quot;">​</a></h2><p>当前<strong>没有系统商店、拍卖行或任务奖励</strong>。获取钻石的主要方式是挖矿、探索和与其他玩家交易。</p><p>主要支出：</p><ul><li>第 9 个及以后的家园：每个 8 钻石。</li><li>公开家园：每个 16 钻石。</li><li>家园领地扩容：注释价 0.05 钻石/格；<strong>当前配置实际 5 钻石/格</strong>（用余额购买额度，见下方价格提示）。</li><li>联盟创建：64 钻石。</li><li>联盟领地扩容：注释价 1 钻石/格；<strong>当前配置实际 100 钻石/格</strong>（从联盟金库扣）。</li></ul><p><strong>价格提示（重要）</strong>：<code>PepperClaim/economy.yml</code> 的注释写的是「0.05 货币/块」与「1 货币/块」，但配置值分别是 <code>5.0</code> 与 <code>100.0</code>；插件把 <code>economy.yml</code> 的数值直接当作「钻石/格」（内部 ×100 存为「分」），并不存在把 0.05 再乘 100 的二次放大；100 倍差异来自配置值本身写成了 <code>5.0</code> 而不是 <code>0.05</code>。按当前配置，家园额度 5 钻石/格（2,048 格 = 10,240 钻石；GUI 一次 256 格 = 1,280 钻石），联盟额度 100 钻石/格（256 格 = 25,600 钻石）。在管理组修正配置前，不建议直接用 GUI 大批购买。</p>',16)])])}const _=e(r,[["render",c]]);export{b as __pageData,_ as default};
